}

/* --- Scrollbar --- */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: var(--black); }
::-webkit-scrollbar-thumb { background: var(--mid-gray); border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: var(--red); }

