[metadata] {"type": "create", "filePath": "/app/output/styles.css", "content": "/* ============================================
   REDROOM FITNESS — Shared Styles
   ============================================ */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --red: #FF0000;
  --red-dark: #CC0000;
  --red-glow: rgba(255, 0, 0, 0.3);
  --black: #0A0A0A;
  --charcoal: #141414;
  --dark-gray: #1A1A1A;
  --mid-gray: #2A2A2A;
  --light-gray: #888;
  --white: #FFFFFF;
  --off-white: #E5E5E5;
  --font-heading: 'Oswald', 'Impact', 'Arial Black', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --max-width: 1200px;
  --nav-height: 80px;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--charcoal);
  color: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }

h1, h2, h3, h4 {
  font-family: var(--font-heading);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  line-height: 1.1;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* --- Top Bar Promo --- */
.top-bar {
  background: var(--red);
  color: var(--white);
  text-align: center;
  padding: 10px 24px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  position: relative;
  z-index: 1001;
}
.top-bar a {
  text-decoration: underline;
  text-underline-offset: 3px;
  margin-left: 8px;
  font-weight: 700;
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(10, 10, 10, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  height: var(--nav-height);
  display: flex;
  align-items: center;
}

.nav .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 24px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--white);
  white-space: nowrap;
}
.nav-logo span { color: var(--red); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-links a {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--off-white);
  transition: color var(--transition);
  white-space: nowrap;
}
.nav-links a:hover,
.nav-links a.active { color: var(--red); }

.nav-utility {
  display: flex;
  align-items: center;
  gap: 16px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 12px 28px;
  border: 2px solid transparent;
  cursor: pointer;
  transition: all var(--transition);
  font-size: 14px;
  white-space: nowrap;
}

.btn-primary {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.btn-primary:hover {
  background: var(--red-dark);
  border-color: var(--red-dark);
  box-shadow: 0 0 30px var(--red-glow);
}

.btn-outline {
  background: transparent;
  color: var(--white);
  border-color: var(--white);
}
.btn-outline:hover {
  background: var(--white);
  color: var(--black);
}

.btn-outline-red {
  background: transparent;
  color: var(--red);
  border-color: var(--red);
}
.btn-outline-red:hover {
  background: var(--red);
  color: var(--white);
}

.btn-sm {
  padding: 8px 18px;
  font-size: 12px;
}

/* --- Mobile Nav Toggle --- */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 8px;
}
.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: var(--transition);
}

/* --- Hero Section --- */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(180deg, rgba(10,10,10,0.4) 0%, rgba(20,20,20,0.85) 60%, var(--charcoal) 100%),
              radial-gradient(ellipse at center, rgba(255,0,0,0.15) 0%, transparent 70%);
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      rgba(255,0,0,0.03) 2px,
      rgba(255,0,0,0.03) 4px
    );
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 40px 24px;
}

.hero-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 12px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--red);
  border: 1px solid rgba(255,0,0,0.4);
  padding: 8px 20px;
  margin-bottom: 32px;
}

.hero h1 {
  font-size: clamp(42px, 8vw, 84px);
  font-weight: 800;
  letter-spacing: 0.02em;
  margin-bottom: 24px;
  line-height: 0.95;
}

.hero h2 {
  font-size: clamp(28px, 5vw, 56px);
  font-weight: 800;
  margin-bottom: 24px;
}

.hero p {
  font-size: clamp(16px, 2.5vw, 20px);
  color: var(--light-gray);
  max-width: 600px;
  margin: 0 auto 36px;
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.hero-subtitle {
  font-size: 14px;
  color: var(--light-gray);
  margin-top: 20px;
  letter-spacing: 0.04em;
}

/* --- Section Common --- */
.section {
  padding: 100px 0;
  position: relative;
}

.section-label {
  font-family: var(--font-heading);
  font-size: 13px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 16px;
  display: block;
}

.section-title {
  font-size: clamp(32px, 5vw, 56px);
  font-weight: 800;
  margin-bottom: 24px;
}

.section-text {
  font-size: 18px;
  color: var(--light-gray);
  max-width: 680px;
  line-height: 1.7;
}

.section-dark { background: var(--black); }
.section-red {
  background: var(--red);
  color: var(--white);
}
.section-red .section-text { color: rgba(255,255,255,0.85); }
.section-red .section-label { color: rgba(255,255,255,0.7); }

/* --- Two Ways Section --- */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  margin-top: 56px;
}

.way-card {
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.06);
  padding: 48px 40px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.way-card::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.way-card:hover { border-color: rgba(255,255,255,0.15); }
.way-card:hover::after { transform: scaleX(1); }

.way-card h3 {
  font-size: 28px;
  margin-bottom: 16px;
}
.way-card h3 span { color: var(--red); }

.way-card p {
  color: var(--light-gray);
  font-size: 16px;
  line-height: 1.7;
}

/* --- Studio Experience --- */
.studio-section {
  background: linear-gradient(180deg, var(--charcoal) 0%, var(--black) 100%);
  text-align: center;
}

.studio-section .section-text {
  margin: 0 auto 48px;
}

.studio-cta-text {
  font-family: var(--font-heading);
  font-size: clamp(18px, 3vw, 24px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  max-width: 700px;
  margin: 0 auto 32px;
}

/* --- Free Trial CTA --- */
.cta-trial {
  background: var(--red);
  text-align: center;
  padding: 80px 0;
}

.cta-trial h2 {
  font-size: clamp(32px, 6vw, 64px);
  margin-bottom: 36px;
}

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.carousel-slide {
  min-width: 100%;
  height: 500px;
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.carousel-slide-inner {
  width: 100%;
  height: 100%;
  position: relative;
}

.slide-gradient {
  position: absolute;
  inset: 0;
  opacity: 0.9;
}

.carousel-caption {
  position: absolute;
  bottom: 60px;
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
  z-index: 3;
}

.carousel-caption h3 {
  font-size: 24px;
  margin-bottom: 8px;
}

.carousel-caption p {
  color: var(--light-gray);
  font-size: 14px;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 5;
  background: rgba(0,0,0,0.6);
  border: 1px solid rgba(255,255,255,0.2);
  color: var(--white);
  width: 48px;
  height: 48px;
  border-radius: 50%;
  cursor: pointer;
  font-size: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}
.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}
.carousel-prev { left: 24px; }
.carousel-next { right: 24px; }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 24px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--mid-gray);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--red); width: 28px; border-radius: 5px; }

/* --- Floor / Treadmill Toggle --- */
.toggle-section {
  text-align: center;
}

.toggle-buttons {
  display: inline-flex;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 4px;
  margin-bottom: 48px;
  overflow: hidden;
}

.toggle-btn {
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 14px 40px;
  background: transparent;
  color: var(--light-gray);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
  position: relative;
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
}

.toggle-content {
  display: none;
  max-width: 700px;
  margin: 0 auto;
  text-align: left;
  animation: fadeIn 0.4s ease;
}
.toggle-content.active { display: block; }

.toggle-content h3 {
  font-size: 28px;
  margin-bottom: 16px;
  text-align: center;
}
.toggle-content p {
  color: var(--light-gray);
  font-size: 18px;
  line-height: 1.7;
  text-align: center;
}

/* --- Weekly Schedule Table --- */
.schedule-table-wrap {
  overflow-x: auto;
  margin-top: 48px;
}

.schedule-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 16px;
}

.schedule-table thead th {
  font-family: var(--font-heading);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 16px 20px;
  text-align: left;
  background: var(--black);
  border-bottom: 2px solid var(--red);
  color: var(--red);
}

.schedule-table tbody td {
  padding: 16px 20px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}

.schedule-table tbody tr {
  transition: background var(--transition);
}
.schedule-table tbody tr:hover {
  background: rgba(255,0,0,0.05);
}

.schedule-table .day-cell {
  font-weight: 700;
  white-space: nowrap;
}

.schedule-table .focus-cell {
  color: var(--off-white);
}

.schedule-table .badge-cell .focus-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 4px 12px;
  background: rgba(255,0,0,0.15);
  color: var(--red);
  border-radius: 2px;
}

/* --- Instructor Grid --- */
.instructor-filters {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}

.filter-btn {
  font-family: var(--font-heading);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 10px 24px;
  background: transparent;
  color: var(--light-gray);
  border: 1px solid rgba(255,255,255,0.15);
  cursor: pointer;
  transition: all var(--transition);
}
.filter-btn:hover {
  border-color: var(--red);
  color: var(--white);
}
.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
}

.instructor-card {
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.06);
  overflow: hidden;
  transition: all var(--transition);
}

.instructor-card:hover {
  border-color: rgba(255,255,255,0.15);
  transform: translateY(-4px);
}

.instructor-card.hidden {
  display: none;
}

.instructor-avatar {
  width: 100%;
  height: 280px;
  position: relative;
  overflow: hidden;
}

.instructor-avatar .avatar-bg {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 72px;
  color: rgba(255,255,255,0.1);
}

.instructor-info {
  padding: 24px;
}

.instructor-info h3 {
  font-size: 22px;
  margin-bottom: 4px;
