.instructor-info .instructor-location {
  font-size: 13px;
  color: var(--red);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 600;
  margin-bottom: 16px;
}

.instructor-info .btn { width: 100%; }

/* --- FAQ Accordion --- */
.faq-list {
  max-width: 760px;
  margin: 48px auto 0;
}

.faq-item {
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  background: none;
  border: none;
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 18px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  text-align: left;
  cursor: pointer;
  transition: color var(--transition);
  gap: 16px;
}

.faq-question:hover { color: var(--red); }

.faq-icon {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 50%;
  font-size: 18px;
  transition: all var(--transition);
  font-family: var(--font-body);
}

.faq-item.open .faq-icon {
  border-color: var(--red);
  color: var(--red);
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 24px;
}

.faq-answer p {
  color: var(--light-gray);
  font-size: 16px;
  line-height: 1.7;
}

/* --- Newsletter --- */
.newsletter {
  background: var(--black);
  text-align: center;
  padding: 80px 0;
}

.newsletter h3 {
  font-size: 32px;
  margin-bottom: 12px;
}

.newsletter p {
  color: var(--light-gray);
  font-size: 16px;
  margin-bottom: 32px;
}

.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 500px;
  margin: 0 auto;
  flex-wrap: wrap;
  justify-content: center;
}

.newsletter-input-wrap {
  flex: 1;
  min-width: 250px;
  position: relative;
}

.newsletter-form input {
  width: 100%;
  padding: 14px 20px;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--white);
  font-family: var(--font-body);
  font-size: 16px;
  outline: none;
  transition: border var(--transition);
}
.newsletter-form input:focus {
  border-color: var(--red);
}
.newsletter-form input.error {
  border-color: var(--red);
}

.newsletter-form .error-msg {
  display: none;
  color: var(--red);
  font-size: 13px;
  margin-top: 8px;
  text-align: left;
}

.newsletter-form .error-msg.visible {
  display: block;
}

.newsletter-success {
  display: none;
  color: #4CAF50;
  font-size: 16px;
  font-weight: 600;
  padding: 16px 0;
}

.newsletter-success.visible {
  display: block;
}

/* --- Country Selector --- */
.country-selector {
  position: relative;
  display: inline-block;
}

.country-select-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--white);
  font-family: var(--font-body);
  font-size: 13px;
  cursor: pointer;
  transition: border var(--transition);
}
.country-select-btn:hover { border-color: rgba(255,255,255,0.3); }
.country-select-btn .arrow { font-size: 10px; margin-left: 4px; }

.country-dropdown {
  display: none;
  position: absolute;
  bottom: 100%;
  left: 0;
  margin-bottom: 4px;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  min-width: 180px;
  z-index: 10;
}

.country-dropdown.open { display: block; }

.country-dropdown button {
  display: block;
  width: 100%;
  padding: 10px 16px;
  background: none;
  border: none;
  color: var(--light-gray);
  font-family: var(--font-body);
  font-size: 13px;
  text-align: left;
  cursor: pointer;
  transition: all var(--transition);
}
.country-dropdown button:hover {
  background: rgba(255,0,0,0.1);
  color: var(--white);
}

/* --- Footer --- */
.footer {
  background: var(--black);
  padding: 80px 0 40px;
  border-top: 1px solid rgba(255,255,255,0.06);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 56px;
}

.footer-brand h3 {
  font-size: 28px;
  margin-bottom: 12px;
}
.footer-brand h3 span { color: var(--red); }
.footer-brand p {
  color: var(--light-gray);
  font-size: 14px;
  line-height: 1.6;
  max-width: 280px;
}

.footer-col h4 {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--red);
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  color: var(--light-gray);
  font-size: 14px;
  padding: 4px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 32px;
  border-top: 1px solid rgba(255,255,255,0.06);
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom p {
  color: var(--light-gray);
  font-size: 13px;
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  transition: all var(--transition);
  color: var(--light-gray);
}
.footer-social a:hover {
  border-color: var(--red);
  color: var(--red);
}

/* --- Page Hero (inner pages) --- */
.page-hero {
  min-height: 50vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(180deg, rgba(10,10,10,0.3) 0%, rgba(20,20,20,0.8) 60%, var(--charcoal) 100%),
              radial-gradient(ellipse at center, rgba(255,0,0,0.1) 0%, transparent 70%);
}

.page-hero .hero-content {
  max-width: 700px;
}

/* --- Features Grid --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
  margin-top: 56px;
}

.feature-card {
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.06);
  padding: 40px 32px;
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: rgba(255,0,0,0.3);
}

.feature-icon {
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255,0,0,0.1);
  border-radius: 50%;
  font-size: 24px;
  margin-bottom: 24px;
  color: var(--red);
}

.feature-card h3 {
  font-size: 20px;
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--light-gray);
  font-size: 15px;
  line-height: 1.6;
}

/* --- Method Section --- */
.method-content {
  max-width: 760px;
  margin: 0 auto;
  text-align: center;
}

.method-content .section-text {
  margin: 0 auto;
}

/* --- Animations --- */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .two-ways-grid {
    grid-template-columns: 1fr;
  }

  .nav-links {
    gap: 20px;
  }
  .nav-links a {
    font-size: 11px;
  }
}

@media (max-width: 768px) {
  :root { --nav-height: 64px; }

  .nav-links, .nav-utility {
    display: none;
  }

  .nav-links.mobile-open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: rgba(10,10,10,0.98);
    backdrop-filter: blur(12px);
    padding: 24px;
    border-bottom: 1px solid rgba(255,255,255,0.06);
    gap: 4px;
  }
  .nav-links.mobile-open a {
    padding: 12px 0;
    font-size: 14px;
  }
  .nav-utility.mobile-open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: calc(var(--nav-height) + 320px);
    left: 0;
    right: 0;
    background: rgba(10,10,10,0.98);
    padding: 0 24px 24px;
    gap: 8px;
  }
  .nav-utility.mobile-open .btn {
    width: 100%;
  }

  .nav-toggle { display: flex; }

  .hero { min-height: 70vh; }
  .hero h1 { font-size: 36px; }

  .section { padding: 60px 0; }

  .carousel-slide { height: 350px; }
  .carousel-btn { width: 40px; height: 40px; font-size: 16px; }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .toggle-buttons {
    flex-direction: column;
    width: 100%;
  }
  .toggle-btn { padding: 14px 24px; }

  .instructor-filters {
    gap: 8px;
  }
  .filter-btn {
    padding: 8px 16px;
    font-size: 11px;
  }
  .instructor-grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .faq-question {
    font-size: 16px;
  }
}

/* --- Scrollbar --- */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: var(--black); }
::-webkit-scrollbar-thumb { background: var(--mid-gray); border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: var(--red); }
