/* ============================================
   REDROOM FITNESS — Shared Styles
   ============================================ */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --red: #FF0000;
  --red-dark: #CC0000;
  --red-glow: rgba(255, 0, 0, 0.3);
  --black: #0A0A0A;
  --charcoal: #141414;
  --dark-gray: #1A1A1A;
  --mid-gray: #2A2A2A;
  --light-gray: #888;
  --white: #FFFFFF;
  --off-white: #E5E5E5;
  --font-heading: 'Oswald', 'Impact', 'Arial Black', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --max-width: 1200px;
  --nav-height: 80px;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--charcoal);
  color: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }

h1, h2, h3, h4 {
  font-family: var(--font-heading);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  line-height: 1.1;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* --- Top Bar Promo --- */
.top-bar {
  background: var(--red);
  color: var(--white);
  text-align: center;
  padding: 10px 24px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  position: relative;
  z-index: 1001;
}
.top-bar a {
  text-decoration: underline;
  text-underline-offset: 3px;
  margin-left: 8px;
  font-weight: 700;
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(10, 10, 10, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  height: var(--nav-height);
  display: flex;
  align-items: center;
}

.nav .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 24px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--white);
  white-space: nowrap;
}
.nav-logo span { color: var(--red); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-links a {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--off-white);
  transition: color var(--transition);
  white-space: nowrap;
}
.nav-links a:hover,
.nav-links a.active { color: var(--red); }

.nav-utility {
  display: flex;
  align-items: center;
  gap: 16px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 12px 28px;
  border: 2px solid transparent;
  cursor: pointer;
  transition: all var(--transition);
  font-size: 14px;
  white-space: nowrap;
}

.btn-primary {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.btn-primary:hover {
  background: var(--red-dark);
  border-color: var(--red-dark);
  box-shadow: 0 0 30px var(--red-glow);
}

.btn-outline {
  background: transparent;
  color: var(--white);
  border-color: var(--white);
}
.btn-outline:hover {
  background: var(--white);
  color: var(--black);
}

.btn-outline-red {
  background: transparent;
  color: var(--red);
  border-color: var(--red);
}
.btn-outline-red:hover {
  background: var(--red);
  color: var(--white);
}

.btn-sm {
  padding: 8px 18px;
  font-size: 12px;
}

/* --- Mobile Nav Toggle --- */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 8px;
}
.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: var(--transition);
}

/* --- Hero Section --- */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(180deg, rgba(10,10,10,0.4) 0%, rgba(20,20,20,0.85) 60%, var(--charcoal) 100%),
              radial-gradient(ellipse at center, rgba(255,0,0,0.15) 0%, transparent 70%);
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      rgba(255,0,0,0.03) 2px,
      rgba(255,0,0,0.03) 4px
    );
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 40px 24px;
}

.hero-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 12px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--red);
  border: 1px solid rgba(255,0,0,0.4);
  padding: 8px 20px;
  margin-bottom: 32px;
}

.hero h1 {
  font-size: clamp(42px, 8vw, 84px);
  font-weight: 800;
  letter-spacing: 0.02em;
  margin-bottom: 24px;
  line-height: 0.95;
}

.hero h2 {
  font-size: clamp(28px, 5vw, 56px);
  font-weight: 800;
  margin-bottom: 24px;
}

.hero p {
  font-size: clamp(16px, 2.5vw, 20px);
  color: var(--light-gray);
  max-width: 600px;
  margin: 0 auto 36px;
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.hero-subtitle {
  font-size: 14px;
  color: var(--light-gray);
  margin-top: 20px;
  letter-spacing: 0.04em;
}

/* --- Section Common --- */
.section {
  padding: 100px 0;
  position: relative;
}

.section-label {
  font-family: var(--font-heading);
  font-size: 13px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 16px;
  display: block;
}

.section-title {
  font-size: clamp(32px, 5vw, 56px);
  font-weight: 800;
  margin-bottom: 24px;
}

.section-text {
  font-size: 18px;
  color: var(--light-gray);
  max-width: 680px;
  line-height: 1.7;
}

.section-dark { background: var(--black); }
.section-red {
  background: var(--red);
  color: var(--white);
}
.section-red .section-text { color: rgba(255,255,255,0.85); }
.section-red .section-label { color: rgba(255,255,255,0.7); }

/* --- Two Ways Section --- */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  margin-top: 56px;
}

.way-card {
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.06);
  padding: 48px 40px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.way-card::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.way-card:hover { border-color: rgba(255,255,255,0.15); }
.way-card:hover::after { transform: scaleX(1); }

.way-card h3 {
  font-size: 28px;
  margin-bottom: 16px;
}
.way-card h3 span { color: var(--red); }

.way-card p {
  color: var(--light-gray);
  font-size: 16px;
  line-height: 1.7;
}

/* --- Studio Experience --- */
.studio-section {
  background: linear-gradient(180deg, var(--charcoal) 0%, var(--black) 100%);
  text-align: center;
}

.studio-section .section-text {
  margin: 0 auto 48px;
}

.studio-cta-text {
  font-family: var(--font-heading);
  font-size: clamp(18px, 3vw, 24px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  max-width: 700px;
  margin: 0 auto 32px;
}

/* --- Free Trial CTA --- */
.cta-trial {
  background: var(--red);
  text-align: center;
  padding: 80px 0;
}

.cta-trial h2 {
  font-size: clamp(32px, 6vw, 64px);
  margin-bottom: 36px;
}

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.carousel-slide {
  min-width: 100%;
  height: 500px;
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.carousel-slide-inner {
  width: 100%;
  height: 100%;
  position: relative;
}

.slide-gradient {
  position: absolute;
  inset: 0;
  opacity: 0.9;
}

.carousel-caption {
  position: absolute;
  bottom: 60px;
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
  z-index: 3;
}

.carousel-caption h3 {
  font-size: 24px;
  margin-bottom: 8px;
}

.carousel-caption p {
  color: var(--light-gray);
  font-size: 14px;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 5;
  background: rgba(0,0,0,0.6);
  border: 1px solid rgba(255,255,255,0.2);
  color: var(--white);
  width: 48px;
  height: 48px;
  border-radius: 50%;
  cursor: pointer;
  font-size: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}
.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}
.carousel-prev { left: 24px; }
.carousel-next { right: 24px; }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 24px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--mid-gray);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--red); width: 28px; border-radius: 5px; }

/* --- Floor / Treadmill Toggle --- */
.toggle-section {
  text-align: center;
}

.toggle-buttons {
  display: inline-flex;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 4px;
  margin-bottom: 48px;
  overflow: hidden;
}

.toggle-btn {
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 14px 40px;
  background: transparent;
  color: var(--light-gray);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
  position: relative;
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
}

.toggle-content {
  display: none;
  max-width: 700px;
  margin: 0 auto;
  text-align: left;
  animation: fadeIn 0.4s ease;
}
.toggle-content.active { display: block; }

.toggle-content h3 {
  font-size: 28px;
  margin-bottom: 16px;
  text-align: center;
}
.toggle-content p {
  color: var(--light-gray);
  font-size: 18px;
  line-height: 1.7;
  text-align: center;
}

/* --- Weekly Schedule Table --- */
.schedule-table-wrap {
  overflow-x: auto;
  margin-top: 48px;
}

.schedule-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 16px;
}

.schedule-table thead th {
  font-family: var(--font-heading);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 16px 20px;
  text-align: left;
  background: var(--black);
  border-bottom: 2px solid var(--red);
  color: var(--red);
}

.schedule-table tbody td {
  padding: 16px 20px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}

.schedule-table tbody tr {
  transition: background var(--transition);
}
.schedule-table tbody tr:hover {
  background: rgba(255,0,0,0.05);
}

.schedule-table .day-cell {
  font-weight: 700;
  white-space: nowrap;
}

.schedule-table .focus-cell {
  color: var(--off-white);
}

.schedule-table .badge-cell .focus-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 4px 12px;
  background: rgba(255,0,0,0.15);
  color: var(--red);
  border-radius: 2px;
}

/* --- Instructor Grid --- */
.instructor-filters {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}

.filter-btn {
  font-family: var(--font-heading);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 10px 24px;
  background: transparent;
  color: var(--light-gray);
  border: 1px solid rgba(255,255,255,0.15);
  cursor: pointer;
  transition: all var(--transition);
}
.filter-btn:hover {
  border-color: var(--red);
  color: var(--white);
}
.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
}

.instructor-card {
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.06);
  overflow: hidden;
  transition: all var(--transition);
}

.instructor-card:hover {
  border-color: rgba(255,255,255,0.15);
  transform: translateY(-4px);
}

.instructor-card.hidden {
  display: none;
}

.instructor-avatar {
  width: 100%;
  height: 280px;
  position: relative;
  overflow: hidden;
}

.instructor-avatar .avatar-bg {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 72px;
  color: rgba(255,255,255,0.1);
}

.instructor-info {
  padding: 24px;
}

.instructor-info h3 {
  font-size: 22px;
  margin-bottom: 4px;
}

.instructor-info .instructor-location {
  font-size: 13px;
  color: var(--red);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 600;
  margin-bottom: 16px;
}

.instructor-info .btn { width: 100%; }

/* --- FAQ Accordion --- */
.faq-list {
  max-width: 760px;
  margin: 48px auto 0;
}

.faq-item {
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  background: none;
  border: none;
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 18px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  text-align: left;
  cursor: pointer;
  transition: color var(--transition);
  gap: 16px;
}

.faq-question:hover { color: var(--red); }

.faq-icon {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 50%;
  font-size: 18px;
  transition: all var(--transition);
  font-family: var(--font-body);
}

.faq-item.open .faq-icon {
  border-color: var(--red);
  color: var(--red);
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 24px;
}

.faq-answer p {
  color: var(--light-gray);
  font-size: 16px;
  line-height: 1.7;
}

/* --- Newsletter --- */
.newsletter {
  background: var(--black);
  text-align: center;
  padding: 80px 0;
}

.newsletter h3 {
  font-size: 32px;
  margin-bottom: 12px;
}

.newsletter p {
  color: var(--light-gray);
  font-size: 16px;
  margin-bottom: 32px;
}

.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 500px;
  margin: 0 auto;
  flex-wrap: wrap;
  justify-content: center;
}

.newsletter-input-wrap {
  flex: 1;
  min-width: 250px;
  position: relative;
}

.newsletter-form input {
  width: 100%;
  padding: 14px 20px;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--white);
  font-family: var(--font-body);
  font-size: 16px;
  outline: none;
  transition: border var(--transition);
}
.newsletter-form input:focus {
  border-color: var(--red);
}
.newsletter-form input.error {
  border-color: var(--red);
}

.newsletter-form .error-msg {
  display: none;
  color: var(--red);
  font-size: 13px;
  margin-top: 8px;
  text-align: left;
}

.newsletter-form .error-msg.visible {
  display: block;
}

.newsletter-success {
  display: none;
  color: #4CAF50;
  font-size: 16px;
  font-weight: 600;
  padding: 16px 0;
}

.newsletter-success.visible {
  display: block;
}

/* --- Country Selector --- */
.country-selector {
  position: relative;
  display: inline-block;
}

.country-select-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--white);
  font-family: var(--font-body);
  font-size: 13px;
  cursor: pointer;
  transition: border var(--transition);
}
.country-select-btn:hover { border-color: rgba(255,255,255,0.3); }
.country-select-btn .arrow { font-size: 10px; margin-left: 4px; }

.country-dropdown {
  display: none;
  position: absolute;
  bottom: 100%;
  left: 0;
  margin-bottom: 4px;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  min-width: 180px;
  z-index: 10;
}

.country-dropdown.open { display: block; }

.country-dropdown button {
  display: block;
  width: 100%;
  padding: 10px 16px;
  background: none;
  border: none;
  color: var(--light-gray);
  font-family: var(--font-body);
  font-size: 13px;
  text-align: left;
  cursor: pointer;
  transition: all var(--transition);
}
.country-dropdown button:hover {
  background: rgba(255,0,0,0.1);
  color: var(--white);
}

/* --- Footer --- */
.footer {
  background: var(--black);
  padding: 80px 0 40px;
  border-top: 1px solid rgba(255,255,255,0.06);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 56px;
}

.footer-brand h3 {
  font-size: 28px;
  margin-bottom: 12px;
}
.footer-brand h3 span { color: var(--red); }
.footer-brand p {
  color: var(--light-gray);
  font-size: 14px;
  line-height: 1.6;
  max-width: 280px;
}

.footer-col h4 {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--red);
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  color: var(--light-gray);
  font-size: 14px;
  padding: 4px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 32px;
  border-top: 1px solid rgba(255,255,255,0.06);
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom p {
  color: var(--light-gray);
  font-size: 13px;
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  transition: all var(--transition);
  color: var(--light-gray);
}
.footer-social a:hover {
  border-color: var(--red);
  color: var(--red);
}

/* --- Page Hero (inner pages) --- */
.page-hero {
  min-height: 50vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(180deg, rgba(10,10,10,0.3) 0%, rgba(20,20,20,0.8) 60%, var(--charcoal) 100%),
              radial-gradient(ellipse at center, rgba(255,0,0,0.1) 0%, transparent 70%);
}

.page-hero .hero-content {
  max-width: 700px;
}

/* --- Features Grid --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
  margin-top: 56px;
}

.feature-card {
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.06);
  padding: 40px 32px;
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: rgba(255,0,0,0.3);
}

.feature-icon {
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255,0,0,0.1);
  border-radius: 50%;
  font-size: 24px;
  margin-bottom: 24px;
  color: var(--red);
}

.feature-card h3 {
  font-size: 20px;
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--light-gray);
  font-size: 15px;
  line-height: 1.6;
}

/* --- Method Section --- */
.method-content {
  max-width: 760px;
  margin: 0 auto;
  text-align: center;
}

.method-content .section-text {
  margin: 0 auto;
}

/* --- Animations --- */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .two-ways-grid {
    grid-template-columns: 1fr;
  }

  .nav-links {
    gap: 20px;
  }
  .nav-links a {
    font-size: 11px;
  }
}

@media (max-width: 768px) {
  :root { --nav-height: 64px; }

  .nav-links, .nav-utility {
    display: none;
  }

  .nav-links.mobile-open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: rgba(10,10,10,0.98);
    backdrop-filter: blur(12px);
    padding: 24px;
    border-bottom: 1px solid rgba(255,255,255,0.06);
    gap: 4px;
  }
  .nav-links.mobile-open a {
    padding: 12px 0;
    font-size: 14px;
  }
  .nav-utility.mobile-open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: calc(var(--nav-height) + 320px);
    left: 0;
    right: 0;
    background: rgba(10,10,10,0.98);
    padding: 0 24px 24px;
    gap: 8px;
  }
  .nav-utility.mobile-open .btn {
    width: 100%;
  }

  .nav-toggle { display: flex; }

  .hero { min-height: 70vh; }
  .hero h1 { font-size: 36px; }

  .section { padding: 60px 0; }

  .carousel-slide { height: 350px; }
  .carousel-btn { width: 40px; height: 40px; font-size: 16px; }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .toggle-buttons {
    flex-direction: column;
    width: 100%;
  }
  .toggle-btn { padding: 14px 24px; }

  .instructor-filters {
    gap: 8px;
  }
  .filter-btn {
    padding: 8px 16px;
    font-size: 11px;
  }
  .instructor-grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .faq-question {
    font-size: 16px;
  }
}

/* --- Scrollbar --- */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: var(--black); }
::-webkit-scrollbar-thumb { background: var(--mid-gray); border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: var(--red); }

/* ============================================
   REDROOM FITNESS — Shared Styles
   ============================================ */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --red: #FF0000;
  --red-dark: #CC0000;
  --red-glow: rgba(255, 0, 0, 0.3);
  --black: #0A0A0A;
  --charcoal: #141414;
  --dark-gray: #1A1A1A;
  --mid-gray: #2A2A2A;
  --light-gray: #888;
  --white: #FFFFFF;
  --off-white: #E5E5E5;
  --font-heading: 'Oswald', 'Impact', 'Arial Black', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --max-width: 1200px;
  --nav-height: 80px;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--charcoal);
  color: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }

h1, h2, h3, h4 {
  font-family: var(--font-heading);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  line-height: 1.1;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* --- Top Bar Promo --- */
.top-bar {
  background: var(--red);
  color: var(--white);
  text-align: center;
  padding: 10px 24px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  position: relative;
  z-index: 1001;
}
.top-bar a {
  text-decoration: underline;
  text-underline-offset: 3px;
  margin-left: 8px;
  font-weight: 700;
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(10, 10, 10, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  height: var(--nav-height);
  display: flex;
  align-items: center;
}

.nav .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 24px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--white);
  white-space: nowrap;
}
.nav-logo span { color: var(--red); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-links a {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--off-white);
  transition: color var(--transition);
  white-space: nowrap;
}
.nav-links a:hover,
.nav-links a.active { color: var(--red); }

.nav-utility {
  display: flex;
  align-items: center;
  gap: 16px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 12px 28px;
  border: 2px solid transparent;
  cursor: pointer;
  transition: all var(--transition);
  font-size: 14px;
  white-space: nowrap;
}

.btn-primary {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.btn-primary:hover {
  background: var(--red-dark);
  border-color: var(--red-dark);
  box-shadow: 0 0 30px var(--red-glow);
}

.btn-outline {
  background: transparent;
  color: var(--white);
  border-color: var(--white);
}
.btn-outline:hover {
  background: var(--white);
  color: var(--black);
}

.btn-outline-red {
  background: transparent;
  color: var(--red);
  border-color: var(--red);
}
.btn-outline-red:hover {
  background: var(--red);
  color: var(--white);
}

.btn-sm {
  padding: 8px 18px;
  font-size: 12px;
}

/* --- Mobile Nav Toggle --- */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 8px;
}
.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: var(--transition);
}

/* --- Hero Section --- */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(180deg, rgba(10,10,10,0.4) 0%, rgba(20,20,20,0.85) 60%, var(--charcoal) 100%),
              radial-gradient(ellipse at center, rgba(255,0,0,0.15) 0%, transparent 70%);
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      rgba(255,0,0,0.03) 2px,
      rgba(255,0,0,0.03) 4px
    );
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 40px 24px;
}

.hero-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 12px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--red);
  border: 1px solid rgba(255,0,0,0.4);
  padding: 8px 20px;
  margin-bottom: 32px;
}

.hero h1 {
  font-size: clamp(42px, 8vw, 84px);
  font-weight: 800;
  letter-spacing: 0.02em;
  margin-bottom: 24px;
  line-height: 0.95;
}

.hero h2 {
  font-size: clamp(28px, 5vw, 56px);
  font-weight: 800;
  margin-bottom: 24px;
}

.hero p {
  font-size: clamp(16px, 2.5vw, 20px);
  color: var(--light-gray);
  max-width: 600px;
  margin: 0 auto 36px;
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.hero-subtitle {
  font-size: 14px;
  color: var(--light-gray);
  margin-top: 20px;
  letter-spacing: 0.04em;
}

/* --- Section Common --- */
.section {
  padding: 100px 0;
  position: relative;
}

.section-label {
  font-family: var(--font-heading);
  font-size: 13px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 16px;
  display: block;
}

.section-title {
  font-size: clamp(32px, 5vw, 56px);
  font-weight: 800;
  margin-bottom: 24px;
}

.section-text {
  font-size: 18px;
  color: var(--light-gray);
  max-width: 680px;
  line-height: 1.7;
}

.section-dark { background: var(--black); }
.section-red {
  background: var(--red);
  color: var(--white);
}
.section-red .section-text { color: rgba(255,255,255,0.85); }
.section-red .section-label { color: rgba(255,255,255,0.7); }

/* --- Two Ways Section --- */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  margin-top: 56px;
}

.way-card {
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.06);
  padding: 48px 40px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.way-card::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.way-card:hover { border-color: rgba(255,255,255,0.15); }
.way-card:hover::after { transform: scaleX(1); }

.way-card h3 {
  font-size: 28px;
  margin-bottom: 16px;
}
.way-card h3 span { color: var(--red); }

.way-card p {
  color: var(--light-gray);
  font-size: 16px;
  line-height: 1.7;
}

/* --- Studio Experience --- */
.studio-section {
  background: linear-gradient(180deg, var(--charcoal) 0%, var(--black) 100%);
  text-align: center;
}

.studio-section .section-text {
  margin: 0 auto 48px;
}

.studio-cta-text {
  font-family: var(--font-heading);
  font-size: clamp(18px, 3vw, 24px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  max-width: 700px;
  margin: 0 auto 32px;
}

/* --- Free Trial CTA --- */
.cta-trial {
  background: var(--red);
  text-align: center;
  padding: 80px 0;
}

.cta-trial h2 {
  font-size: clamp(32px, 6vw, 64px);
  margin-bottom: 36px;
}

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.carousel-slide {
  min-width: 100%;
  height: 500px;
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.carousel-slide-inner {
  width: 100%;
  height: 100%;
  position: relative;
}

.slide-gradient {
  position: absolute;
  inset: 0;
  opacity: 0.9;
}

.carousel-caption {
  position: absolute;
  bottom: 60px;
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
  z-index: 3;
}

.carousel-caption h3 {
  font-size: 24px;
  margin-bottom: 8px;
}

.carousel-caption p {
  color: var(--light-gray);
  font-size: 14px;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 5;
  background: rgba(0,0,0,0.6);
  border: 1px solid rgba(255,255,255,0.2);
  color: var(--white);
  width: 48px;
  height: 48px;
  border-radius: 50%;
  cursor: pointer;
  font-size: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}
.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}
.carousel-prev { left: 24px; }
.carousel-next { right: 24px; }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 24px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--mid-gray);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--red); width: 28px; border-radius: 5px; }

/* --- Floor / Treadmill Toggle --- */
.toggle-section {
  text-align: center;
}

.toggle-buttons {
  display: inline-flex;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 4px;
  margin-bottom: 48px;
  overflow: hidden;
}

.toggle-btn {
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 14px 40px;
  background: transparent;
  color: var(--light-gray);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
  position: relative;
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
}

.toggle-content {
  display: none;
  max-width: 700px;
  margin: 0 auto;
  text-align: left;
  animation: fadeIn 0.4s ease;
}
.toggle-content.active { display: block; }

.toggle-content h3 {
  font-size: 28px;
  margin-bottom: 16px;
  text-align: center;
}
.toggle-content p {
  color: var(--light-gray);
  font-size: 18px;
  line-height: 1.7;
  text-align: center;
}

/* --- Weekly Schedule Table --- */
.schedule-table-wrap {
  overflow-x: auto;
  margin-top: 48px;
}

.schedule-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 16px;
}

.schedule-table thead th {
  font-family: var(--font-heading);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 16px 20px;
  text-align: left;
  background: var(--black);
  border-bottom: 2px solid var(--red);
  color: var(--red);
}

.schedule-table tbody td {
  padding: 16px 20px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}

.schedule-table tbody tr {
  transition: background var(--transition);
}
.schedule-table tbody tr:hover {
  background: rgba(255,0,0,0.05);
}

.schedule-table .day-cell {
  font-weight: 700;
  white-space: nowrap;
}

.schedule-table .focus-cell {
  color: var(--off-white);
}

.schedule-table .badge-cell .focus-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 4px 12px;
  background: rgba(255,0,0,0.15);
  color: var(--red);
  border-radius: 2px;
}

/* --- Instructor Grid --- */
.instructor-filters {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}

.filter-btn {
  font-family: var(--font-heading);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 10px 24px;
  background: transparent;
  color: var(--light-gray);
  border: 1px solid rgba(255,255,255,0.15);
  cursor: pointer;
  transition: all var(--transition);
}
.filter-btn:hover {
  border-color: var(--red);
  color: var(--white);
}
.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
}

.instructor-card {
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.06);
  overflow: hidden;
  transition: all var(--transition);
}

.instructor-card:hover {
  border-color: rgba(255,255,255,0.15);
  transform: translateY(-4px);
}

.instructor-card.hidden {
  display: none;
}

.instructor-avatar {
  width: 100%;
  height: 280px;
  position: relative;
  overflow: hidden;
}

.instructor-avatar .avatar-bg {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 72px;
  color: rgba(255,255,255,0.1);
}

.instructor-info {
  padding: 24px;
}

.instructor-info h3 {
  font-size: 22px;
  margin-bottom: 4px;
}

.instructor-info .instructor-location {
  font-size: 13px;
  color: var(--red);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 600;
  margin-bottom: 16px;
}

.instructor-info .btn { width: 100%; }

/* --- FAQ Accordion --- */
.faq-list {
  max-width: 760px;
  margin: 48px auto 0;
}

.faq-item {
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  background: none;
  border: none;
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 18px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  text-align: left;
  cursor: pointer;
  transition: color var(--transition);
  gap: 16px;
}

.faq-question:hover { color: var(--red); }

.faq-icon {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 50%;
  font-size: 18px;
  transition: all var(--transition);
  font-family: var(--font-body);
}

.faq-item.open .faq-icon {
  border-color: var(--red);
  color: var(--red);
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 24px;
}

.faq-answer p {
  color: var(--light-gray);
  font-size: 16px;
  line-height: 1.7;
}

/* --- Newsletter --- */
.newsletter {
  background: var(--black);
  text-align: center;
  padding: 80px 0;
}

.newsletter h3 {
  font-size: 32px;
  margin-bottom: 12px;
}

.newsletter p {
  color: var(--light-gray);
  font-size: 16px;
  margin-bottom: 32px;
}

.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 500px;
  margin: 0 auto;
  flex-wrap: wrap;
  justify-content: center;
}

.newsletter-input-wrap {
  flex: 1;
  min-width: 250px;
  position: relative;
}

.newsletter-form input {
  width: 100%;
  padding: 14px 20px;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--white);
  font-family: var(--font-body);
  font-size: 16px;
  outline: none;
  transition: border var(--transition);
}
.newsletter-form input:focus {
  border-color: var(--red);
}
.newsletter-form input.error {
  border-color: var(--red);
}

.newsletter-form .error-msg {
  display: none;
  color: var(--red);
  font-size: 13px;
  margin-top: 8px;
  text-align: left;
}

.newsletter-form .error-msg.visible {
  display: block;
}

.newsletter-success {
  display: none;
  color: #4CAF50;
  font-size: 16px;
  font-weight: 600;
  padding: 16px 0;
}

.newsletter-success.visible {
  display: block;
}

/* --- Country Selector --- */
.country-selector {
  position: relative;
  display: inline-block;
}

.country-select-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--white);
  font-family: var(--font-body);
  font-size: 13px;
  cursor: pointer;
  transition: border var(--transition);
}
.country-select-btn:hover { border-color: rgba(255,255,255,0.3); }
.country-select-btn .arrow { font-size: 10px; margin-left: 4px; }

.country-dropdown {
  display: none;
  position: absolute;
  bottom: 100%;
  left: 0;
  margin-bottom: 4px;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  min-width: 180px;
  z-index: 10;
}

.country-dropdown.open { display: block; }

.country-dropdown button {
  display: block;
  width: 100%;
  padding: 10px 16px;
  background: none;
  border: none;
  color: var(--light-gray);
  font-family: var(--font-body);
  font-size: 13px;
  text-align: left;
  cursor: pointer;
  transition: all var(--transition);
}
.country-dropdown button:hover {
  background: rgba(255,0,0,0.1);
  color: var(--white);
}

/* --- Footer --- */
.footer {
  background: var(--black);
  padding: 80px 0 40px;
  border-top: 1px solid rgba(255,255,255,0.06);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 56px;
}

.footer-brand h3 {
  font-size: 28px;
  margin-bottom: 12px;
}
.footer-brand h3 span { color: var(--red); }
.footer-brand p {
  color: var(--light-gray);
  font-size: 14px;
  line-height: 1.6;
  max-width: 280px;
}

.footer-col h4 {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--red);
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  color: var(--light-gray);
  font-size: 14px;
  padding: 4px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 32px;
  border-top: 1px solid rgba(255,255,255,0.06);
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom p {
  color: var(--light-gray);
  font-size: 13px;
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  transition: all var(--transition);
  color: var(--light-gray);
}
.footer-social a:hover {
  border-color: var(--red);
  color: var(--red);
}

/* --- Page Hero (inner pages) --- */
.page-hero {
  min-height: 50vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(180deg, rgba(10,10,10,0.3) 0%, rgba(20,20,20,0.8) 60%, var(--charcoal) 100%),
              radial-gradient(ellipse at center, rgba(255,0,0,0.1) 0%, transparent 70%);
}

.page-hero .hero-content {
  max-width: 700px;
}

/* --- Features Grid --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
  margin-top: 56px;
}

.feature-card {
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.06);
  padding: 40px 32px;
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: rgba(255,0,0,0.3);
}

.feature-icon {
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255,0,0,0.1);
  border-radius: 50%;
  font-size: 24px;
  margin-bottom: 24px;
  color: var(--red);
}

.feature-card h3 {
  font-size: 20px;
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--light-gray);
  font-size: 15px;
  line-height: 1.6;
}

/* --- Method Section --- */
.method-content {
  max-width: 760px;
  margin: 0 auto;
  text-align: center;
}

.method-content .section-text {
  margin: 0 auto;
}

/* --- Animations --- */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .two-ways-grid {
    grid-template-columns: 1fr;
  }

  .nav-links {
    gap: 20px;
  }
  .nav-links a {
    font-size: 11px;
  }
}

@media (max-width: 768px) {
  :root { --nav-height: 64px; }

  .nav-links, .nav-utility {
    display: none;
  }

  .nav-links.mobile-open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: rgba(10,10,10,0.98);
    backdrop-filter: blur(12px);
    padding: 24px;
    border-bottom: 1px solid rgba(255,255,255,0.06);
    gap: 4px;
  }
  .nav-links.mobile-open a {
    padding: 12px 0;
    font-size: 14px;
  }
  .nav-utility.mobile-open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: calc(var(--nav-height) + 320px);
    left: 0;
    right: 0;
    background: rgba(10,10,10,0.98);
    padding: 0 24px 24px;
    gap: 8px;
  }
  .nav-utility.mobile-open .btn {
    width: 100%;
  }

  .nav-toggle { display: flex; }

  .hero { min-height: 70vh; }
  .hero h1 { font-size: 36px; }

  .section { padding: 60px 0; }

  .carousel-slide { height: 350px; }
  .carousel-btn { width: 40px; height: 40px; font-size: 16px; }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .toggle-buttons {
    flex-direction: column;
    width: 100%;
  }
  .toggle-btn { padding: 14px 24px; }

  .instructor-filters {
    gap: 8px;
  }
  .filter-btn {
    padding: 8px 16px;
    font-size: 11px;
  }
  .instructor-grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .faq-question {
    font-size: 16px;
  }
}

/* --- Scrollbar --- */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: var(--black); }
::-webkit-scrollbar-thumb { background: var(--mid-gray); border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: var(--red); }

raw_arguments.content:
/* ============================================
   REDROOM FITNESS — Shared Styles
   ============================================ */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --red: #FF0000;
  --red-dark: #CC0000;
  --red-glow: rgba(255, 0, 0, 0.3);
  --black: #0A0A0A;
  --charcoal: #141414;
  --dark-gray: #1A1A1A;
  --mid-gray: #2A2A2A;
  --light-gray: #888;
  --white: #FFFFFF;
  --off-white: #E5E5E5;
  --font-heading: 'Oswald', 'Impact', 'Arial Black', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --max-width: 1200px;
  --nav-height: 80px;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--charcoal);
  color: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }

h1, h2, h3, h4 {
  font-family: var(--font-heading);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  line-height: 1.1;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* --- Top Bar Promo --- */
.top-bar {
  background: var(--red);
  color: var(--white);
  text-align: center;
  padding: 10px 24px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  position: relative;
  z-index: 1001;
}
.top-bar a {
  text-decoration: underline;
  text-underline-offset: 3px;
  margin-left: 8px;
  font-weight: 700;
}

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(10, 10, 10, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  height: var(--nav-height);
  display: flex;
  align-items: center;
}

.nav .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 24px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--white);
  white-space: nowrap;
}
.nav-logo span { color: var(--red); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-links a {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--off-white);
  transition: color var(--transition);
  white-space: nowrap;
}
.nav-links a:hover,
.nav-links a.active { color: var(--red); }

.nav-utility {
  display: flex;
  align-items: center;
  gap: 16px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 12px 28px;
  border: 2px solid transparent;
  cursor: pointer;
  transition: all var(--transition);
  font-size: 14px;
  white-space: nowrap;
}

.btn-primary {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.btn-primary:hover {
  background: var(--red-dark);
  border-color: var(--red-dark);
  box-shadow: 0 0 30px var(--red-glow);
}

.btn-outline {
  background: transparent;
  color: var(--white);
  border-color: var(--white);
}
.btn-outline:hover {
  background: var(--white);
  color: var(--black);
}

.btn-outline-red {
  background: transparent;
  color: var(--red);
  border-color: var(--red);
}
.btn-outline-red:hover {
  background: var(--red);
  color: var(--white);
}

.btn-sm {
  padding: 8px 18px;
  font-size: 12px;
}

/* --- Mobile Nav Toggle --- */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 8px;
}
.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: var(--transition);
}

/* --- Hero Section --- */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(180deg, rgba(10,10,10,0.4) 0%, rgba(20,20,20,0.85) 60%, var(--charcoal) 100%),
              radial-gradient(ellipse at center, rgba(255,0,0,0.15) 0%, transparent 70%);
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      rgba(255,0,0,0.03) 2px,
      rgba(255,0,0,0.03) 4px
    );
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 40px 24px;
}

.hero-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 12px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--red);
  border: 1px solid rgba(255,0,0,0.4);
  padding: 8px 20px;
  margin-bottom: 32px;
}

.hero h1 {
  font-size: clamp(42px, 8vw, 84px);
  font-weight: 800;
  letter-spacing: 0.02em;
  margin-bottom: 24px;
  line-height: 0.95;
}

.hero h2 {
  font-size: clamp(28px, 5vw, 56px);
  font-weight: 800;
  margin-bottom: 24px;
}

.hero p {
  font-size: clamp(16px, 2.5vw, 20px);
  color: var(--light-gray);
  max-width: 600px;
  margin: 0 auto 36px;
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.hero-subtitle {
  font-size: 14px;
  color: var(--light-gray);
  margin-top: 20px;
  letter-spacing: 0.04em;
}

/* --- Section Common --- */
.section {
  padding: 100px 0;
  position: relative;
}

.section-label {
  font-family: var(--font-heading);
  font-size: 13px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 16px;
  display: block;
}

.section-title {
  font-size: clamp(32px, 5vw, 56px);
  font-weight: 800;
  margin-bottom: 24px;
}

.section-text {
  font-size: 18px;
  color: var(--light-gray);
  max-width: 680px;
  line-height: 1.7;
}

.section-dark { background: var(--black); }
.section-red {
  background: var(--red);
  color: var(--white);
}
.section-red .section-text { color: rgba(255,255,255,0.85); }
.section-red .section-label { color: rgba(255,255,255,0.7); }

/* --- Two Ways Section --- */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  margin-top: 56px;
}

.way-card {
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.06);
  padding: 48px 40px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.way-card::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.way-card:hover { border-color: rgba(255,255,255,0.15); }
.way-card:hover::after { transform: scaleX(1); }

.way-card h3 {
  font-size: 28px;
  margin-bottom: 16px;
}
.way-card h3 span { color: var(--red); }

.way-card p {
  color: var(--light-gray);
  font-size: 16px;
  line-height: 1.7;
}

/* --- Studio Experience --- */
.studio-section {
  background: linear-gradient(180deg, var(--charcoal) 0%, var(--black) 100%);
  text-align: center;
}

.studio-section .section-text {
  margin: 0 auto 48px;
}

.studio-cta-text {
  font-family: var(--font-heading);
  font-size: clamp(18px, 3vw, 24px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  max-width: 700px;
  margin: 0 auto 32px;
}

/* --- Free Trial CTA --- */
.cta-trial {
  background: var(--red);
  text-align: center;
  padding: 80px 0;
}

.cta-trial h2 {
  font-size: clamp(32px, 6vw, 64px);
  margin-bottom: 36px;
}

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.carousel-slide {
  min-width: 100%;
  height: 500px;
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.carousel-slide-inner {
  width: 100%;
  height: 100%;
  position: relative;
}

.slide-gradient {
  position: absolute;
  inset: 0;
  opacity: 0.9;
}

.carousel-caption {
  position: absolute;
  bottom: 60px;
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
  z-index: 3;
}

.carousel-caption h3 {
  font-size: 24px;
  margin-bottom: 8px;
}

.carousel-caption p {
  color: var(--light-gray);
  font-size: 14px;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 5;
  background: rgba(0,0,0,0.6);
  border: 1px solid rgba(255,255,255,0.2);
  color: var(--white);
  width: 48px;
  height: 48px;
  border-radius: 50%;
  cursor: pointer;
  font-size: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}
.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}
.carousel-prev { left: 24px; }
.carousel-next { right: 24px; }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 24px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--mid-gray);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--red); width: 28px; border-radius: 5px; }

/* --- Floor / Treadmill Toggle --- */
.toggle-section {
  text-align: center;
}

.toggle-buttons {
  display: inline-flex;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 4px;
  margin-bottom: 48px;
  overflow: hidden;
}

.toggle-btn {
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 14px 40px;
  background: transparent;
  color: var(--light-gray);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
  position: relative;
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
}

.toggle-content {
  display: none;
  max-width: 700px;
  margin: 0 auto;
  text-align: left;
  animation: fadeIn 0.4s ease;
}
.toggle-content.active { display: block; }

.toggle-content h3 {
  font-size: 28px;
  margin-bottom: 16px;
  text-align: center;
}
.toggle-content p {
  color: var(--light-gray);
  font-size: 18px;
  line-height: 1.7;
  text-align: center;
}

/* --- Weekly Schedule Table --- */
.schedule-table-wrap {
  overflow-x: auto;
  margin-top: 48px;
}

.schedule-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 16px;
}

.schedule-table thead th {
  font-family: var(--font-heading);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 16px 20px;
  text-align: left;
  background: var(--black);
  border-bottom: 2px solid var(--red);
  color: var(--red);
}

.schedule-table tbody td {
  padding: 16px 20px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}

.schedule-table tbody tr {
  transition: background var(--transition);
}
.schedule-table tbody tr:hover {
  background: rgba(255,0,0,0.05);
}

.schedule-table .day-cell {
  font-weight: 700;
  white-space: nowrap;
}

.schedule-table .focus-cell {
  color: var(--off-white);
}

.schedule-table .badge-cell .focus-badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 4px 12px;
  background: rgba(255,0,0,0.15);
  color: var(--red);
  border-radius: 2px;
}

/* --- Instructor Grid --- */
.instructor-filters {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}

.filter-btn {
  font-family: var(--font-heading);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 10px 24px;
  background: transparent;
  color: var(--light-gray);
  border: 1px solid rgba(255,255,255,0.15);
  cursor: pointer;
  transition: all var(--transition);
}
.filter-btn:hover {
  border-color: var(--red);
  color: var(--white);
}
.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
}

.instructor-card {
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.06);
  overflow: hidden;
  transition: all var(--transition);
}

.instructor-card:hover {
  border-color: rgba(255,255,255,0.15);
  transform: translateY(-4px);
}

.instructor-card.hidden {
  display: none;
}

.instructor-avatar {
  width: 100%;
  height: 280px;
  position: relative;
  overflow: hidden;
}

.instructor-avatar .avatar-bg {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 72px;
  color: rgba(255,255,255,0.1);
}

.instructor-info {
  padding: 24px;
}

.instructor-info h3 {
  font-size: 22px;
  margin-bottom: 4px;
}

.instructor-info .instructor-location {
  font-size: 13px;
  color: var(--red);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 600;
  margin-bottom: 16px;
}

.instructor-info .btn { width: 100%; }

/* --- FAQ Accordion --- */
.faq-list {
  max-width: 760px;
  margin: 48px auto 0;
}

.faq-item {
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  background: none;
  border: none;
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 18px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  text-align: left;
  cursor: pointer;
  transition: color var(--transition);
  gap: 16px;
}

.faq-question:hover { color: var(--red); }

.faq-icon {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 50%;
  font-size: 18px;
  transition: all var(--transition);
  font-family: var(--font-body);
}

.faq-item.open .faq-icon {
  border-color: var(--red);
  color: var(--red);
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 24px;
}

.faq-answer p {
  color: var(--light-gray);
  font-size: 16px;
  line-height: 1.7;
}

/* --- Newsletter --- */
.newsletter {
  background: var(--black);
  text-align: center;
  padding: 80px 0;
}

.newsletter h3 {
  font-size: 32px;
  margin-bottom: 12px;
}

.newsletter p {
  color: var(--light-gray);
  font-size: 16px;
  margin-bottom: 32px;
}

.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 500px;
  margin: 0 auto;
  flex-wrap: wrap;
  justify-content: center;
}

.newsletter-input-wrap {
  flex: 1;
  min-width: 250px;
  position: relative;
}

.newsletter-form input {
  width: 100%;
  padding: 14px 20px;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--white);
  font-family: var(--font-body);
  font-size: 16px;
  outline: none;
  transition: border var(--transition);
}
.newsletter-form input:focus {
  border-color: var(--red);
}
.newsletter-form input.error {
  border-color: var(--red);
}

.newsletter-form .error-msg {
  display: none;
  color: var(--red);
  font-size: 13px;
  margin-top: 8px;
  text-align: left;
}

.newsletter-form .error-msg.visible {
  display: block;
}

.newsletter-success {
  display: none;
  color: #4CAF50;
  font-size: 16px;
  font-weight: 600;
  padding: 16px 0;
}

.newsletter-success.visible {
  display: block;
}

/* --- Country Selector --- */
.country-selector {
  position: relative;
  display: inline-block;
}

.country-select-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--white);
  font-family: var(--font-body);
  font-size: 13px;
  cursor: pointer;
  transition: border var(--transition);
}
.country-select-btn:hover { border-color: rgba(255,255,255,0.3); }
.country-select-btn .arrow { font-size: 10px; margin-left: 4px; }

.country-dropdown {
  display: none;
  position: absolute;
  bottom: 100%;
  left: 0;
  margin-bottom: 4px;
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.1);
  min-width: 180px;
  z-index: 10;
}

.country-dropdown.open { display: block; }

.country-dropdown button {
  display: block;
  width: 100%;
  padding: 10px 16px;
  background: none;
  border: none;
  color: var(--light-gray);
  font-family: var(--font-body);
  font-size: 13px;
  text-align: left;
  cursor: pointer;
  transition: all var(--transition);
}
.country-dropdown button:hover {
  background: rgba(255,0,0,0.1);
  color: var(--white);
}

/* --- Footer --- */
.footer {
  background: var(--black);
  padding: 80px 0 40px;
  border-top: 1px solid rgba(255,255,255,0.06);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 56px;
}

.footer-brand h3 {
  font-size: 28px;
  margin-bottom: 12px;
}
.footer-brand h3 span { color: var(--red); }
.footer-brand p {
  color: var(--light-gray);
  font-size: 14px;
  line-height: 1.6;
  max-width: 280px;
}

.footer-col h4 {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--red);
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  color: var(--light-gray);
  font-size: 14px;
  padding: 4px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 32px;
  border-top: 1px solid rgba(255,255,255,0.06);
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom p {
  color: var(--light-gray);
  font-size: 13px;
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  transition: all var(--transition);
  color: var(--light-gray);
}
.footer-social a:hover {
  border-color: var(--red);
  color: var(--red);
}

/* --- Page Hero (inner pages) --- */
.page-hero {
  min-height: 50vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(180deg, rgba(10,10,10,0.3) 0%, rgba(20,20,20,0.8) 60%, var(--charcoal) 100%),
              radial-gradient(ellipse at center, rgba(255,0,0,0.1) 0%, transparent 70%);
}

.page-hero .hero-content {
  max-width: 700px;
}

/* --- Features Grid --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
  margin-top: 56px;
}

.feature-card {
  background: var(--dark-gray);
  border: 1px solid rgba(255,255,255,0.06);
  padding: 40px 32px;
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: rgba(255,0,0,0.3);
}

.feature-icon {
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255,0,0,0.1);
  border-radius: 50%;
  font-size: 24px;
  margin-bottom: 24px;
  color: var(--red);
}

.feature-card h3 {
  font-size: 20px;
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--light-gray);
  font-size: 15px;
  line-height: 1.6;
}

/* --- Method Section --- */
.method-content {
  max-width: 760px;
  margin: 0 auto;
  text-align: center;
}

.method-content .section-text {
  margin: 0 auto;
}

/* --- Animations --- */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .two-ways-grid {
    grid-template-columns: 1fr;
  }

  .nav-links {
    gap: 20px;
  }
  .nav-links a {
    font-size: 11px;
  }
}

@media (max-width: 768px) {
  :root { --nav-height: 64px; }

  .nav-links, .nav-utility {
    display: none;
  }

  .nav-links.mobile-open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: rgba(10,10,10,0.98);
    backdrop-filter: blur(12px);
    padding: 24px;
    border-bottom: 1px solid rgba(255,255,255,0.06);
    gap: 4px;
  }
  .nav-links.mobile-open a {
    padding: 12px 0;
    font-size: 14px;
  }
  .nav-utility.mobile-open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: calc(var(--nav-height) + 320px);
    left: 0;
    right: 0;
    background: rgba(10,10,10,0.98);
    padding: 0 24px 24px;
    gap: 8px;
  }
  .nav-utility.mobile-open .btn {
    width: 100%;
  }

  .nav-toggle { display: flex; }

  .hero { min-height: 70vh; }
  .hero h1 { font-size: 36px; }

  .section { padding: 60px 0; }

  .carousel-slide { height: 350px; }
  .carousel-btn { width: 40px; height: 40px; font-size: 16px; }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .toggle-buttons {
    flex-direction: column;
    width: 100%;
  }
  .toggle-btn { padding: 14px 24px; }

  .instructor-filters {
    gap: 8px;
  }
  .filter-btn {
    padding: 8px 16px;
    font-size: 11px;
  }
  .instructor-grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .faq-question {
    font-size: 16px;
  }
}

/* --- Scrollbar --- */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: var(--black); }
::-webkit-scrollbar-thumb { background: var(--mid-gray); border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: var(--red); }

